import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { detectClaudeInstallScopes, pluginUpdateScopes, } from "./installScope.js";
let home;
beforeEach(() => {
    home = fs.mkdtempSync(path.join(os.tmpdir(), "bitfab-installscope-"));
});
afterEach(() => {
    fs.rmSync(home, { recursive: true, force: true });
});
function writeInstalledPlugins(payload) {
    const dir = path.join(home, ".claude", "plugins");
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, "installed_plugins.json"), JSON.stringify(payload));
}
const PROJECT = path.join(path.sep, "tmp", "some", "project");
describe("detectClaudeInstallScopes", () => {
    it("returns the scope when the plugin is installed at user scope", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [{ scope: "user", version: "0.1.56" }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([
            "user",
        ]);
    });
    it("returns the project scope when only installed at project scope", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [
                    {
                        scope: "project",
                        projectPath: PROJECT,
                        version: "0.1.53",
                    },
                ],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([
            "project",
        ]);
    });
    it("returns both scopes when installed at user and project", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [
                    { scope: "user", version: "0.1.56" },
                    {
                        scope: "project",
                        projectPath: PROJECT,
                        version: "0.1.53",
                    },
                ],
            },
        });
        const scopes = detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT);
        expect(scopes.sort()).toEqual(["project", "user"]);
    });
    it("deduplicates repeated scopes (e.g. multiple project installs)", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [
                    { scope: "project", projectPath: PROJECT },
                    { scope: "project", projectPath: path.join(PROJECT, "nested") },
                ],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([
            "project",
        ]);
    });
    it("ignores a project install belonging to another project", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [
                    {
                        scope: "project",
                        projectPath: path.join(path.sep, "other", "repo"),
                    },
                ],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([]);
    });
    it("keeps the user-scope install when another project also has one", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [
                    { scope: "user" },
                    {
                        scope: "project",
                        projectPath: path.join(path.sep, "other", "repo"),
                    },
                ],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([
            "user",
        ]);
    });
    it("matches a project install from a subdirectory of the project", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [{ scope: "local", projectPath: PROJECT }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, path.join(PROJECT, "packages", "web"))).toEqual(["local"]);
    });
    it("does not treat a sibling directory as inside the project", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [{ scope: "project", projectPath: PROJECT }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, `${PROJECT}-other`)).toEqual([]);
    });
    it("returns an empty array when the plugin key is absent", () => {
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "other@marketplace": [{ scope: "user" }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([]);
    });
    it("returns an empty array when the file does not exist", () => {
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([]);
    });
    it("returns an empty array when the file is malformed", () => {
        const dir = path.join(home, ".claude", "plugins");
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(path.join(dir, "installed_plugins.json"), "not-json{");
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, PROJECT)).toEqual([]);
    });
});
describe("pluginUpdateScopes", () => {
    it("defaults to user scope when detection found nothing", () => {
        expect(pluginUpdateScopes([])).toEqual(["user"]);
    });
    it("passes through detected scopes", () => {
        const scopes = ["project", "local"];
        expect(pluginUpdateScopes(scopes)).toEqual(["project", "local"]);
    });
});
describe("detectClaudeInstallScopes symlinked projects", () => {
    it("matches a project reached through a symlink", () => {
        const real = path.join(home, "real-project");
        const link = path.join(home, "linked-project");
        fs.mkdirSync(real, { recursive: true });
        fs.symlinkSync(real, link);
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [{ scope: "project", projectPath: real }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, link)).toEqual([
            "project",
        ]);
    });
    it("matches when the recorded path is the symlink and cwd is the real path", () => {
        const real = path.join(home, "real-project");
        const link = path.join(home, "linked-project");
        fs.mkdirSync(real, { recursive: true });
        fs.symlinkSync(real, link);
        writeInstalledPlugins({
            version: 2,
            plugins: {
                "bitfab@bitfab": [{ scope: "project", projectPath: link }],
            },
        });
        expect(detectClaudeInstallScopes("bitfab@bitfab", home, real)).toEqual([
            "project",
        ]);
    });
});
